      const c = document.querySelector(".roamjs-tldraw-canvas-container");
      const el = c?.querySelector(".tl-canvas") || c?.querySelector(".tl-container");
      if (!el) return null;
      const key = Object.keys(el).find((k) => k.startsWith("__reactFiber$"));
      let f = key ? el[key] : null;
      for (let i = 0; f && i < 400; i += 1, f = f.return) {
        const p = f.memoizedProps;
        if (isEd(p?.editor)) return p.editor;
        if (isEd(p?.value)) return p.value;
      }
      return null;
    };
    return true;
  });

const closeDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    if (!(await page.evaluate(() => Boolean(document.querySelector(".bp3-dialog, .rm-settings"))))) return;
    await page.keyboard.press("Escape");
    await sleep(page, 400);
  }
};

const mouseDrag = async (page, from, to, steps = 15) => {
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  for (let i = 1; i <= steps; i += 1) {
    await page.mouse.move(from.x + ((to.x - from.x) * i) / steps, from.y + ((to.y - from.y) * i) / steps);
    await sleep(page, 25);
  }
  await page.mouse.up();
};

const shapeCenter = (page, id) =>
  page.evaluate((id) => {
    const ed = window.__e2244Ed();
    const b = ed.getShapePageBounds(id);
    const p = ed.pageToScreen({ x: b.midX, y: b.midY });
    return { x: p.x, y: p.y };
  }, id);

const dropdown = (page) => page.locator(".roamjs-tldraw-canvas-container div.shadow-lg").filter({ hasText: "Relation Type" }).first();
const dropdownButtons = async (page) => (await dropdown(page).locator("button").allInnerTexts()).map((t) => t.replace(/\s+/g, " ").trim());
const dropdownVisible = async (page) => (await dropdown(page).count()) > 0 && (await dropdown(page).isVisible());

const dragHandle = async (page, fromId, toId) => {
  await page.evaluate(() => { window.__e2244Ed().selectNone(); return true; });
  const c = await shapeCenter(page, fromId);
  await page.mouse.click(c.x, c.y);
  await sleep(page, 600);
  const handles = page.locator(".roamjs-tldraw-canvas-container .cursor-crosshair");
  const n = await handles.count();
  if (!n) throw new Error("no drag handles after selecting node");
  const t = await shapeCenter(page, toId);
  let best = null; let bestD = Infinity;
  for (let i = 0; i < n; i += 1) {
    const b = await handles.nth(i).boundingBox();
    const d = b ? Math.hypot(b.x - t.x, b.y - t.y) : Infinity;
    if (d < bestD) { best = b; bestD = d; }
  }
  await mouseDrag(page, { x: best.x + best.width / 2, y: best.y + best.height / 2 }, t);
  await sleep(page, 800);
  if (!(await dropdownVisible(page))) {
    const toast = await page.locator(".tlui-toast__container").allInnerTexts().catch(() => []);
    throw new Error(`relation menu did not open; toasts: ${JSON.stringify(toast)}`);
  }
};

const clickExact = async (page, text) => {
