const shapeUtilRegistered = (page, id) => page.evaluate((id) => Boolean(window.__e2244Ed().shapeUtils[id]), id);

const waitForEditor = async (page) => {
  await installEditorFinder(page);
  const start = Date.now();
  while (Date.now() - start < 60000) {
    if (await page.evaluate(() => Boolean(window.__e2244Ed?.())).catch(() => false)) return;
