};

const centreOn = (page) =>
  page.evaluate(() => {
    const ed = window.__e2244Ed();
    ed.zoomToFit();
    const cam = ed.getCamera();
    ed.setCamera({ ...cam, y: cam.y - 140 / cam.z });
    return true;
  });

export default {
  async ready({ page }) {
    await closeDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const out = { shots: {} };
    const logs = [];
    page.on("console", (m) => { if (["error", "warning"].includes(m.type())) logs.push(`[${m.type()}] ${m.text().slice(0, 250)}`); });
    page.on("pageerror", (e) => logs.push(`[pageerror] ${String(e?.message || e).slice(0, 250)}`));
    const flush = () => fs.writeFileSync(`${outDir}/reload-result.json`, JSON.stringify(out, null, 2));
    const step = async (name, fn) => {
      try { out[name] = await fn(); } catch (e) { out[name] = { error: String(e?.message || e).slice(0, 600) }; }
      flush();
      return out[name];
    };
    const shot = async (name) => { const p = `${outDir}/${name}`; await page.screenshot({ path: p }); out.shots[name] = p; return p; };

    if ((await globalRelations(page)).some((r) => `${r.label}${r.complement}`.includes(MARK))) throw new Error("marker already present; refusing to run");

    await step("buildAndSetting", async () => {
      const label = await openSettings(page);
      const text = await page.locator(".bp3-dialog").first().innerText().catch(() => "");
      const stamp = text.match(/v0\.\d+\.\d+-\S+/)?.[0] ?? null;
      const initial = (await label.count()) ? await label.locator("input").isChecked().catch(() => null) : null;
      await closeDialogs(page);
      if (EXPECT_STAMP && !(stamp || "").includes(EXPECT_STAMP)) throw new Error(`wrong build loaded: stamp ${stamp}, expected ${EXPECT_STAMP}`);
      let toggled = null;
      if (initial === false) { toggled = await setStoredRelations(page, true); enabledByTest = toggled.checked === true; }
      return { stamp, initial, toggled };
    });
    if (out.buildAndSetting.error) throw new Error(out.buildAndSetting.error);

    const F = await step("fixtures", async () => {
      // TX exists before mount, so it is registered and offered by Add existing for other pairs.
      const TX = await createTriplet(page, { label: LX, complement: CX, source: NODE.conclusion, destination: NODE.consequence });
      const fmt = await page.evaluate(() => {
        const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
        const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/string :block/props]}]", [":node/title", "roam/js/discourse-graph"]);
        const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
        return g(gb?.[":block/props"], "Canvas page format");
      });
      const titles = { canvas: (fmt && fmt.includes("*") ? fmt : "Canvas/*").replace("*", `${MARK} canvas ${TS}`), other: `${MARK} away ${TS}`, q: `${MARK} question ${TS}`, h: `${MARK} hypothesis ${TS}`, x: `${MARK} conclusion ${TS}`, y: `${MARK} consequence ${TS}` };
      const uids = {};
      for (const [k, t] of Object.entries(titles)) {
        uids[k] = windowUid();
        await page.evaluate(({ t, u }) => window.roamAlphaAPI.data.page.create({ page: { title: t, uid: u } }), { t, u: uids[k] });
      }
      await sleep(page, 1500);
      return { TX, titles, uids };
    });
    if (F.error) throw new Error(F.error);

    await step("openCanvas", async () => {
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.canvas);
      await waitForEditor(page);
      await closeDialogs(page);
      await page.evaluate((n) => {
        const ed = window.__e2244Ed();
        ed.createShapes([
          { id: "shape:q", type: "discourse-node", x: 0, y: 0, props: { uid: n.q.uid, title: n.q.title, nodeTypeId: n.q.type, w: 220, h: 90 } },
          { id: "shape:h", type: "discourse-node", x: 600, y: 0, props: { uid: n.h.uid, title: n.h.title, nodeTypeId: n.h.type, w: 220, h: 90 } },
          { id: "shape:x", type: "discourse-node", x: 0, y: 400, props: { uid: n.x.uid, title: n.x.title, nodeTypeId: n.x.type, w: 220, h: 90 } },
          { id: "shape:y", type: "discourse-node", x: 600, y: 400, props: { uid: n.y.uid, title: n.y.title, nodeTypeId: n.y.type, w: 220, h: 90 } },
        ]);
        return true;
      }, {
        q: { uid: F.uids.q, title: F.titles.q, type: NODE.question },
        h: { uid: F.uids.h, title: F.titles.h, type: NODE.hypothesis },
        x: { uid: F.uids.x, title: F.titles.x, type: NODE.conclusion },
        y: { uid: F.uids.y, title: F.titles.y, type: NODE.consequence },
      });
      await centreOn(page);
      await sleep(page, 1500);
      return { txRegistered: await shapeUtilRegistered(page, F.TX) };
    });

    // 1. Add existing on an empty pair: reload toast, menu closes, new id is not drawable or offered yet.
    out.addExisting = await step("addExisting", async () => {
      await dragHandle(page, "shape:q", "shape:h");
      const emptyState = await dropdownButtons(page);
      await clickExact(page, "Add existing");
      await sleep(page, 600);
      const rows = (await dropdownButtons(page)).filter((t) => t.includes(MARK));
      const row = dropdown(page).locator("button").filter({ hasText: LX }).first();
      await row.click();
      const t = await toastInfo(page, "Reload to draw it");
      await shot("1-add-existing-reload-toast.png");
      const menuOpen = await dropdownVisible(page);
      const created = (await globalRelations(page)).filter((r) => r.label === LX && r.source === NODE.question && r.destination === NODE.hypothesis);
      const newId = created[0]?.id;
      const registered = newId ? await shapeUtilRegistered(page, newId) : null;
      await dismissToasts(page);
      await dragHandle(page, "shape:q", "shape:h");
      const listAgain = await dropdownButtons(page);
      await page.keyboard.press("Escape"); await sleep(page, 400);
      return { emptyState, rows, toast: t, menuOpen, created, newId, registered, listAgain,
        pass: Boolean(t.body.includes("Discourse relation added") && t.buttons.includes("Reload") && !menuOpen && created.length === 1 && registered === false && !listAgain.includes(LX)) };
    });

    // 2. Create new on a pair that already has types: same reload toast, titled "Relation type created".
    out.createNew = await step("createNew", async () => {
      await dragHandle(page, "shape:x", "shape:y");
      const list = await dropdownButtons(page);
      await dropdown(page).locator("button[aria-label='Add relation type']").click();
      await sleep(page, 300);
      await clickExact(page, "Create new");
      await sleep(page, 500);
      await page.locator("#dg-new-relation-label").fill(LN);
      await page.locator("#dg-new-relation-complement").fill(CN);
      await dialog(page).locator("button", { hasText: "Continue" }).click();
      const t = await toastInfo(page, "Reload to draw it");
      await shot("2-create-new-reload-toast.png");
      const dialogClosed = !(await dialogOpen(page));
      const menuOpen = await dropdownVisible(page);
      const created = (await globalRelations(page)).filter((r) => r.label === LN && r.source === NODE.conclusion && r.destination === NODE.consequence);
      const newId = created[0]?.id;
      const registered = newId ? await shapeUtilRegistered(page, newId) : null;
      await dismissToasts(page);
      return { list, toast: t, dialogClosed, menuOpen, created, newId, registered,
        pass: Boolean(list.includes(LX) && t.body.includes("Relation type created") && t.buttons.includes("Reload") && dialogClosed && !menuOpen && created.length === 1 && registered === false) };
    });

    // 3. Remount (what a reload does for shape utils): both new types register, list and draw.
    out.afterRemount = await step("afterRemount", async () => {
      const idA = out.addExisting?.newId;
      const idB = out.createNew?.newId;
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.other);
      await sleep(page, 2500);
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.canvas);
      await waitForEditor(page);
      await closeDialogs(page);
      await centreOn(page);
      await sleep(page, 1500);
      const registeredA = await shapeUtilRegistered(page, idA);
      const registeredB = await shapeUtilRegistered(page, idB);
      await dragHandle(page, "shape:q", "shape:h");
      const listQH = await dropdownButtons(page);
      await clickExact(page, LX);
      await sleep(page, 5000);
      await dragHandle(page, "shape:x", "shape:y");
      const listXY = await dropdownButtons(page);
      await clickExact(page, LN);
      await sleep(page, 5000);
      await page.evaluate(() => { window.__e2244Ed().selectNone(); return true; });
      await sleep(page, 400);
      await shot("3-after-remount-arrows.png");
      const arrows = await page.evaluate(() => window.__e2244Ed().getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => ({ id: s.id, type: s.type, text: s.props?.text })));
      const stored = await storedRelations(page, [F.uids.q, F.uids.h, F.uids.x, F.uids.y]);
      const storedA = stored.filter((s) => s.hasSchema === idA && s.sourceUid === F.uids.q && s.destinationUid === F.uids.h);
      const storedB = stored.filter((s) => s.hasSchema === idB && s.sourceUid === F.uids.x && s.destinationUid === F.uids.y);
      return { registeredA, registeredB, listQH, listXY, arrows, storedA, storedB,
        pass: Boolean(registeredA && registeredB && listQH.includes(LX) && listXY.includes(LN) && arrows.some((a) => a.type === idA) && arrows.some((a) => a.type === idB) && storedA.length === 1 && storedB.length === 1) };
    });

    // 4. Arrows survive another remount and render.
    out.existingArrows = await step("existingArrows", async () => {
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.other);
      await sleep(page, 2000);
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.canvas);
      await waitForEditor(page);
      await closeDialogs(page);
      await centreOn(page);
      await sleep(page, 2500);
      const arrows = await page.evaluate(() => {
        const ed = window.__e2244Ed();
        return ed.getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => ({ type: s.type, rendered: Boolean(document.querySelector(`[data-shape-id="${s.id}"]`)) }));
      });
      await shot("4-arrows-after-second-remount.png");
      return { arrows, pass: arrows.length >= 2 && arrows.every((a) => a.rendered) };
    });

    out.errors = logs.filter((l) => !/create-space|Could not log in|ERR_CONNECTION_REFUSED|Failed to create space/.test(l)).slice(0, 30);
    flush();
    return { addExisting: out.addExisting?.pass, createNew: out.createNew?.pass, afterRemount: out.afterRemount?.pass, existingArrows: out.existingArrows?.pass, errors: out.errors.length, result: `${outDir}/reload-result.json` };
  },
  async cleanup({ page, outDir }) {
    const res = { enabledByTest };
    await page.keyboard.press("Escape").catch(() => {});
    await page.evaluate(() => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { title: "roam/js/discourse-graph" } })).catch(() => {});
    await sleep(page, 1500);
    const pages = await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find ?u ?t :where [?p :node/title ?t] [?p :block/uid ?u] [(clojure.string/includes? ?t "${mark}")]]`), MARK);
    const nodeUids = pages.map(([u]) => u);
    const stored = await storedRelations(page, nodeUids);
    for (const s of stored) await page.evaluate((u) => window.roamAlphaAPI.data.block.delete({ block: { uid: u } }), s.uid);
    res.deletedStoredRelations = stored.length;
    res.triplets = await deleteMarkedTriplets(page);
    for (const [u] of pages) await page.evaluate((u) => window.roamAlphaAPI.data.page.delete({ page: { uid: u } }), u);
    res.deletedPages = pages.length;
    await sleep(page, 1500);
    const strays = await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find ?u :where [?b :block/string ?s] [?b :block/uid ?u] [(clojure.string/includes? ?s "${mark}")]]`), MARK);
    for (const [u] of strays) await page.evaluate((u) => window.roamAlphaAPI.data.block.delete({ block: { uid: u } }), u);
    res.deletedStrayBlocks = strays.length;
    await sleep(page, 2500);
    res.remaining = {
      pages: await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find (count ?p) . :where [?p :node/title ?t] [(clojure.string/includes? ?t "${mark}")]]`), MARK),
      blocks: await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find (count ?b) . :where [?b :block/string ?s] [(clojure.string/includes? ?s "${mark}")]]`), MARK),
